INSERT INTO public.academy_shared_data(key,value) VALUES ('original.cells.등하원_월수금.0001','[{"c":"C165","v":"박 서 진A"},{"c":"D165","v":"반포르엘 마을버스정류장"},{"c":"E165","v":"       수        "},{"c":"F165","v":"1093833297"},{"c":"H165","v":"0.91597222222222219","f":"_xlfn.LET(\n    _xlpm.base_data, _xlfn.LET(\n        _xlpm.schedule_range, 등하원_스케줄_관리!$B$3:$I$1000,\n        _xlpm.enroll_range, 입관원서!$A$1:$H$1000,\n        _xlpm.enroll_header, INDEX(_xlpm.enroll_range, 1, 0),\n        _xlpm.enroll_data, _xlfn.DROP(_xlpm.enroll_range, 1),\n        _xlpm.id_col, _xlfn.XMATCH(\"고유번호\", _xlpm.enroll_header),\n        _xlpm.phone_col, _xlfn.XMATCH(\"연락처\", _xlpm.enroll_header),\n        _xlpm.id_data, _xlfn.SCAN(\"\", INDEX(_xlpm.schedule_range, 0, 1), _xlfn.LAMBDA(_xlpm.a,_xlpm.v, IF(_xlpm.v<>\"\", _xlpm.v, _xlpm.a))),\n        _xlpm.name_data, _xlfn.SCAN(\"\", INDEX(_xlpm.schedule_range, 0, 2), _xlfn.LAMBDA(_xlpm.a,_xlpm.v, IF(_xlpm.v<>\"\", _xlpm.v, _xlpm.a))),\n        _xlpm.phones, IFERROR(_xlfn.XLOOKUP(_xlpm.id_data, _xlfn.CHOOSECOLS(_xlpm.enroll_data, _xlpm.id_col), _xlfn.CHOOSECOLS(_xlpm.enroll_data, _xlpm.phone_col), \"\"), \"\"),\n        _xlpm.clean_schedule, _xlfn.HSTACK(_xlpm.id_data, _xlpm.name_data, _xlpm.schedule_range, _xlpm.phones),\n        _xlpm.filtered_2pm_data, _xlfn._xlws.FILTER(\n            _xlpm.clean_schedule,\n            (IF(INDEX(_xlpm.clean_schedule, 0, 9) >= TIME(0,55,0),\n                TIME(HOUR(INDEX(_xlpm.clean_schedule, 0, 9) - TIME(0,55,0)),0,0),\n                \"\"\n            ) = TIME(21,0,0)) *\n            (INDEX(_xlpm.clean_schedule, 0, 10) <> \"\") *\n            ISNUMBER(_xlfn.XMATCH(INDEX(_xlpm.clean_schedule, 0, 6), {\"월\";\"수\";\"금\"})),\n            \"\"\n        ),\n        IFERROR(_xlfn.CHOOSECOLS(_xlfn._xlws.SORT(_xlpm.filtered_2pm_data, {9,10,2}), 9, 2, 10, 6, 11),\n                {\"\",\"\",\"\",\"\",\"\"})\n    ),\n    _xlpm.grouped_data, _xlfn.GROUPBY(\n        _xlfn.CHOOSECOLS(_xlpm.base_data, 1, 2, 3, 5),\n        INDEX(_xlpm.base_data, 0, 4),\n        _xlfn.LAMBDA(_xlpm.d, _xlfn.TEXTJOIN(\"   \", TRUE,\n            _xlfn.MAP({\"월\";\"수\";\"금\"}, _xlfn.LAMBDA(_xlpm.day, IF(ISNUMBER(_xlfn.XMATCH(_xlpm.day, _xlpm.d, 0)), _xlpm.day&\" \", \"    \")))\n        )),\n        0, 0\n    ),\n    _xlpm.final_output, _xlfn.CHOOSECOLS(_xlpm.grouped_data, 1, 2, 3, 5, 4),\n    _xlpm.pattern_key, _xlfn.BYROW(INDEX(_xlpm.final_output,,4), _xlfn.LAMBDA(_xlpm.r, TRIM(SUBSTITUTE(_xlpm.r,\" \",\"\")))),\n    _xlpm.pattern_rank, IFERROR(\n        _xlfn.XMATCH(_xlpm.pattern_key, {\"월수금\",\"월수\",\"월금\",\"수금\",\"월\",\"수\",\"금\"}, 0, 1),\n        999\n    ),\n    _xlfn.SORTBY(_xlpm.final_output,\n        INDEX(_xlpm.final_output,,1), 1,\n        INDEX(_xlpm.final_output,,3), 1,\n        _xlpm.pattern_rank,          1,\n        INDEX(_xlpm.final_output,,2), 1\n    )\n)"},{"c":"I165","v":"최 은 서A"},{"c":"J165","v":"현대자동차블루핸즈"},{"c":"K165","v":"월               "},{"c":"L165","v":"1074114489"},{"c":"O165","v":"2시"},{"c":"B166","v":"0.85486111111111107"},{"c":"C166","v":"박 서 현B"},{"c":"D166","v":"반포르엘 마을버스정류장"},{"c":"E166","v":"       수        "},{"c":"F166","v":"1093833297"},{"c":"H166","v":"0.91736111111111107"},{"c":"I166","v":"강 다 현"},{"c":"J166","v":"반포르엘 마을버스정류장"},{"c":"K166","v":"       수        "},{"c":"L166","v":"1086147066"},{"c":"O166","v":"3시"},{"c":"B167","v":"0.85486111111111107"},{"c":"C167","v":"오 연 우"},{"c":"D167","v":"반포르엘 마을버스정류장"},{"c":"E167","v":"       수        "},{"c":"F167","v":"010-3114-5463"},{"c":"H167","v":"0.91736111111111107"},{"c":"I167","v":"강 문 채"},{"c":"J167","v":"반포르엘 마을버스정류장"},{"c":"K167","v":"       수        "},{"c":"L167","v":"1086147066"},{"c":"O167","v":"4시"},{"c":"B168","v":"0.8569444444444444"},{"c":"C168","v":"김 소 민"},{"c":"D168","v":"하나유치원앞"},{"c":"E168","v":"              금 "},{"c":"F168","v":"010-5918-8927"},{"c":"H168","v":"0.91736111111111107"},{"c":"I168","v":"박 서 진A"},{"c":"J168","v":"반포르엘 마을버스정류장"},{"c":"K168","v":"       수        "},{"c":"L168","v":"1093833297"